export const FORK_LIMITS = Object.freeze({
  maxConversations: 30,
  maxMessages: 100,
  maxMessageLength: 12000,
  maxTitle: 80,
  maxBranchesPerParent: 8,
  maxDepth: 4,
  maxSnippet: 180,
  maxForkNote: 400,
  maxId: 120,
  maxAlternate: 3,
  maxToolActivities: 4
});

export const FORK_ERRORS = Object.freeze({
  messageNotFound: 'MESSAGE_NOT_FOUND',
  depthLimit: 'DEPTH_LIMIT',
  branchLimit: 'BRANCH_LIMIT',
  conversationLimit: 'CONVERSATION_LIMIT',
  emptyFork: 'EMPTY_FORK'
});

export function cleanForkText(value, limit) {
  return typeof value === 'string' ? value.trim().replace(/�/g, '').slice(0, limit) : '';
}

export function createForkId() {
  return globalThis.crypto?.randomUUID?.() ||
    String(Date.now()) + '-' + Math.random().toString(16).slice(2) + '-' + Math.random().toString(16).slice(2);
}

export function normalizeForkMessage(message, idFactory = createForkId) {
  if (!message || typeof message !== 'object') return null;
  const role = message.role === 'assistant' ? 'assistant' : message.role === 'user' ? 'user' : '';
  const content = cleanForkText(message.content, FORK_LIMITS.maxMessageLength);
  if (!role || !content) return null;

  const result = {
    id: cleanForkText(message.id, FORK_LIMITS.maxId) || idFactory(),
    role,
    content,
    at: cleanForkText(message.at, 40) || new Date().toISOString()
  };

  if (Array.isArray(message.toolActivities)) {
    result.toolActivities = message.toolActivities
      .filter((item) => item && typeof item === 'object' && typeof item.label === 'string')
      .slice(0, FORK_LIMITS.maxToolActivities)
      .map((item) => ({
        label: cleanForkText(item.label, 80),
        state: item.state === 'running' || item.state === 'failure' ? item.state : 'success'
      }))
      .filter((item) => item.label);
  }

  if (Array.isArray(message.alternates)) {
    result.alternates = message.alternates
      .filter((item) => typeof item === 'string')
      .map((item) => item.slice(0, FORK_LIMITS.maxMessageLength))
      .filter(Boolean)
      .slice(0, FORK_LIMITS.maxAlternate);
  }

  if (message.feedback === 'positive' || message.feedback === 'negative') result.feedback = message.feedback;

  if (message.generation && typeof message.generation === 'object') {
    result.generation = {
      model: cleanForkText(message.generation.model, 160),
      agentId: cleanForkText(message.generation.agentId, 120),
      toolsEnabled: message.generation.toolsEnabled === true,
      generatedAt: cleanForkText(message.generation.generatedAt, 40),
      durationMs: Number.isFinite(message.generation.durationMs) && message.generation.durationMs >= 0
        ? Math.min(600000, Math.floor(message.generation.durationMs))
        : null
    };
  }

  return result;
}

export function getConversationDepth(conversation, all) {
  let depth = 0;
  let cursor = conversation;
  const seen = new Set();
  while (cursor?.forkOf && depth < FORK_LIMITS.maxDepth + 2) {
    if (seen.has(cursor.id)) return FORK_LIMITS.maxDepth + 1;
    seen.add(cursor.id);
    cursor = all.find((item) => item.id === cursor.forkOf) || null;
    depth += 1;
  }
  return depth;
}

export function countDirectBranches(parentId, all) {
  return all.filter((item) => item && item.forkOf === parentId).length;
}

export function createFork(source, messageId, all, { idFactory = createForkId, now = () => new Date().toISOString(), title = '', note = '' } = {}) {
  const index = Array.isArray(source?.messages)
    ? source.messages.findIndex((message) => message?.id === messageId)
    : -1;
  if (index < 0) return { error: FORK_ERRORS.messageNotFound };

  const depth = getConversationDepth(source, all);
  if (depth >= FORK_LIMITS.maxDepth) return { error: FORK_ERRORS.depthLimit };
  if (countDirectBranches(source.id, all) >= FORK_LIMITS.maxBranchesPerParent) return { error: FORK_ERRORS.branchLimit };
  if (all.length >= FORK_LIMITS.maxConversations) return { error: FORK_ERRORS.conversationLimit };

  const messages = source.messages.slice(0, index + 1)
    .map((message) => normalizeForkMessage(message, idFactory))
    .filter(Boolean)
    .slice(-FORK_LIMITS.maxMessages);

  if (!messages.length) return { error: FORK_ERRORS.emptyFork };

  const stamp = now();
  const ordinal = countDirectBranches(source.id, all) + 1;
  const baseTitle = cleanForkText(source.title, FORK_LIMITS.maxTitle) || 'Sohbet';
  const requestedTitle = cleanForkText(title, FORK_LIMITS.maxTitle);
  const branchTitle = requestedTitle || ('↳ ' + baseTitle + ' · Dal ' + ordinal);

  return {
    conversation: {
      id: idFactory(),
      title: branchTitle.slice(0, FORK_LIMITS.maxTitle),
      agentId: cleanForkText(source.agentId, 120),
      toolsEnabled: source.toolsEnabled === true,
      createdAt: stamp,
      updatedAt: stamp,
      messages,
      forkOf: cleanForkText(source.id, FORK_LIMITS.maxId),
      forkMessageId: cleanForkText(messageId, FORK_LIMITS.maxId),
      forkDepth: depth + 1,
      ...(cleanForkText(note, FORK_LIMITS.maxForkNote) ? { forkNote: cleanForkText(note, FORK_LIMITS.maxForkNote) } : {})
    }
  };
}

export function directChildren(conversationId, all) {
  return all
    .filter((item) => item?.forkOf === conversationId)
    .sort((a, b) => String(b.updatedAt || '').localeCompare(String(a.updatedAt || '')))
    .slice(0, FORK_LIMITS.maxBranchesPerParent);
}

export function conversationLineage(conversation, all) {
  const chain = [];
  const seen = new Set();
  let cursor = conversation;
  while (cursor && !seen.has(cursor.id) && chain.length <= FORK_LIMITS.maxDepth + 1) {
    chain.unshift(cursor);
    seen.add(cursor.id);
    cursor = cursor.forkOf ? all.find((item) => item.id === cursor.forkOf) || null : null;
  }
  return chain;
}

export function buildForkSnapshot(conversation, exportedAt = new Date().toISOString()) {
  return {
    version: 1,
    type: 'hafize-conversation-fork',
    exportedAt,
    conversation
  };
}